#include <stdio.h>
#define MAXN 16
int parent[MAXN], rk[MAXN];
int find(int x){ int r=x; while(parent[r]!=r) r=parent[r];
    while(parent[x]!=r){ int t=parent[x]; parent[x]=r; x=t; } return r; }
void unite(int a,int b){ int ra=find(a),rb=find(b); if(ra==rb) return;
    if(rk[ra]<rk[rb]) parent[ra]=rb; else if(rk[ra]>rk[rb]) parent[rb]=ra;
    else { parent[rb]=ra; rk[ra]++; } }
int main(void){
    int n=5;
    for(int i=0;i<n;i++){ parent[i]=i; rk[i]=0; }
    int edges[][2]={{1,2},{2,3},{3,4},{1,4},{4,5}};
    int E=5, ba=-1, bb=-1;
    for(int i=0;i<E;i++){
        int a=edges[i][0]-1, b=edges[i][1]-1;
        int ra=find(a), rb=find(b);
        if(ra==rb){
            ba=edges[i][0]; bb=edges[i][1];
            printf("加入边 (%d,%d) 时 %d 与 %d 已连通 -> 成环，为冗余边\n",
                   edges[i][0],edges[i][1],edges[i][0],edges[i][1]);
            break;
        }
        unite(a,b);
    }
    printf("冗余连接 = (%d, %d)\n", ba, bb);
    return 0;
}
